fn even_odd_count(num: int) -> (int, int) {
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
    >>> even_odd_count(-12) 
    (1, 1)
    >>> even_odd_count(123) 
    (1, 2)
    """
    var even = 0
    var odd = 0
    for c in str(abs(num)) {
        d = ord(c) - ord("0")
