fn do_algebra(operator: [str], operand: [int]) -> int {
    n = len(operand)
    var rv: [int] = []
    var ro: [str] = []
    var cur = operand[n - 1]
    var i = n - 2
    while i >= 0 {
        if operator[i] == "**" {
            cur = operand[i] ** cur
        } else {
            rv.append(cur)
            ro.append(operator[i])
            cur = operand[i]
        }
        i -= 1
    }
    rv.append(cur)
    rv.reverse()
    ro.reverse()

    var vals: [int] = []
    var ops: [str] = []
    var acc = rv[0]
    for j in range(len(ro)) {
        o = ro[j]
        nxt = rv[j + 1]
        if o == "*" {
            acc = acc * nxt
        } elif o == "//" {
            acc = acc // nxt
        } else {
            vals.append(acc)
            ops.append(o)
            acc = nxt
        }
        vals.append(acc)
    }

    var result = vals[0]
    for j in range(len(ops)) {
        if ops[j] == "+" {
            result = result + vals[j + 1]
        } else {
            result = result - vals[j + 1]
        }
    }
    return result
}
