fn generate_integers(a: int, b: int) -> [int] {
    """
    Given two positive integers a and b, return the even digits between a
    and b, in ascending order.
    """
    lo = max(2, min(a, b))
    hi = min(8, max(a, b))
    var result: [int] = []
    for i in range(lo, hi + 1) {
        if i % 2 == 0 {
