fn largest_divisor(n: int) -> int {
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    var d = n // 2
    while d > 1 {
        if n % d == 0 {
            return d
        }
        d -= 1
    }
    return 1
}
