fn strange_sort_list(lst: [int]) -> [int] {
    """
    Given list of integers, return list in strange order.
    Strange sorting, is when you start with the minimum value,
    then maximum of the remaining integers, then minimum and so on.
    """
    var sorted_list = sorted(lst)
    var result: [int] = []
    var lo = 0
    var hi = len(sorted_list) - 1
    var take_min = True
    while lo <= hi {
        if take_min {
            result.append(sorted_list[lo])
            lo += 1
        } else {
            result.append(sorted_list[hi])
            hi -= 1
        }
        take_min = not take_min
    }
    return result
}
