fn pancake_sort(nums: [int]) -> [int] {
    """
    Write a function to sort a list of elements.
    """
    var arr = nums
    var size = len(arr)
    while size > 1 {
        var mi = 0
        for i in range(size) {
            if arr[i] > arr[mi] {
                mi = i
            }
        }
        if mi != size - 1 {
            if mi > 0 {
                var head = arr[0:mi + 1]
                head.reverse()
                var rest = arr[mi + 1:len(arr)]
                arr = head + rest
            }
            var head2 = arr[0:size]
            head2.reverse()
            var rest2 = arr[size:len(arr)]
            arr = head2 + rest2
        }
        size -= 1
    }
    return arr
}
