fn shell_sort(my_list: [int]) -> [int] {
    """
    Write a function to sort the given array by using shell sort.
    """
    var arr = my_list
    var gap = len(arr) // 2
    while gap > 0 {
        var i = gap
        while i < len(arr) {
            temp = arr[i]
            var j = i
            while j >= gap and arr[j - gap] > temp {
                arr[j] = arr[j - gap]
                j -= gap
            }
            arr[j] = temp
            i += 1
        }
        gap = gap // 2
    }
    return arr
}
