fn comb_sort(nums: [int]) -> [int] {
    """
    Write a function to sort a list of elements.
    """
    var xs = nums
    n = len(xs)
    var gap = n
    var swapped = True
    while gap != 1 or swapped {
        gap = (gap * 10) // 13
        if gap < 1 {
            gap = 1
        }
        swapped = False
        var i = 0
        while i + gap < n {
            if xs[i] > xs[i + gap] {
                tmp = xs[i]
                xs[i] = xs[i + gap]
                xs[i + gap] = tmp
                swapped = True
            }
            i += 1
        }
    }
    return xs
}
