fn power_base_sum(base: int, power: int) -> int {
    """
    Write a function that takes base and power as arguments and calculate the sum of all digits of the base to the specified power.
    """
    var digits: [int] = [1]
    b = abs(base)
    var i = 0
    while i < power {
        var carry = 0
        var j = 0
        while j < len(digits) {
            cur = digits[j] * b + carry
            digits[j] = cur % 10
            carry = cur // 10
            j += 1
        }
        if carry > 0 {
            digits.append(carry % 10)
            carry = carry // 10
        }
        i += 1
    }
    return sum(digits)
}
```

